var components = { carousel: carousel_default, toast: toast_default, chat: chat_default, select: select_default, link: link_default, collapse: collapse_default, stat: stat_default, hovergallery: hovergallery_default, aura: aura_default, range: range_default, megamenu: megamenu_default, stack: stack_default, fieldset: fieldset_default, breadcrumbs: breadcrumbs_default, modal: modal_default, hero: hero_default, loading: loading_default, calendar: calendar_default, timeline: timeline_default, radio: radio_default, progress: progress_default, filter: filter_default, status: status_default, table: table_default, tooltip: tooltip_default, drawer: drawer_default, tab: tab_default, fileinput: fileinput_default, hover3d: hover3d_default, menu: menu_default, list: list_default, mockup: mockup_default, card: card_default, footer: footer_default, otp: otp_default, kbd: kbd_default, dock: dock_default, label: label_default, divider: divider_default, mask: mask_default, indicator: indicator_default, skeleton: skeleton_default, toggle: toggle_default, input: input_default, validator: validator_default, steps: steps_default, navbar: navbar_default, rating: rating_default, textrotate: textrotate_default, radialprogress: radialprogress_default, alert: alert_default, badge: badge_default, textarea: textarea_default, countdown: countdown_default, dropdown: dropdown_default, swap: swap_default, fab: fab_default, checkbox: checkbox_default, avatar: avatar_default, diff: diff_default, button: button_default };
var utilities = { join: join_default, radius: radius_default, typography: typography_default, glass: glass_default };

// packages/daisyui/index.js
var version = "5.7.28";
var daisyui_default = plugin.withOptions((options) => {
  return ({ addBase, addComponents, addUtilities, addVariant }) => {
    const {
      include,
      exclude,
      prefix = ""
    } = pluginOptionsHandler(options, addBase, object_default, version);
    const shouldIncludeItem = (name) => {
      if (include && exclude) {
        return include.includes(name) && !exclude.includes(name);
      }
      if (include) {
        return include.includes(name);
      }
      if (exclude) {
        return !exclude.includes(name);
      }
      return true;
    };
    Object.entries(base).forEach(([name, item]) => {
      if (!shouldIncludeItem(name))
        return;
      item({ addBase, prefix });
    });
    Object.entries(components).forEach(([name, item]) => {
      if (!shouldIncludeItem(name))
        return;
      item({
        addComponents: (styles) => addComponents(nestCssLayers(styles)),
        prefix
      });
    });
    Object.entries(utilities).forEach(([name, item]) => {
      if (!shouldIncludeItem(name))
        return;
      item({
        addUtilities: (styles) => addUtilities(nestCssLayers(styles)),
        prefix
      });
    });
    addVariant(`${prefix}is-drawer-close`, `&:where(.${prefix}drawer-toggle:not(:checked) ~ .${prefix}drawer-side, .${prefix}drawer-toggle:not(:checked) ~ .${prefix}drawer-side *)`);
    addVariant(`${prefix}is-drawer-open`, `&:where(.${prefix}drawer-toggle:checked ~ .${prefix}drawer-side, .${prefix}drawer-toggle:checked ~ .${prefix}drawer-side *)`);
  };
}, () => ({
  theme: {
    extend: variables_default
  }
}));


